-- Minimal DDL of the dpg_app tables served by the generic Admin resources (column names/types/nullability copied from
-- the TEST database). RLS is enabled like in the real schema so the role grants + policies are what is exercised.
create table dpg_app.blog_categories (id serial primary key, name varchar(100) not null, slug varchar(100) not null unique, description text, thumbnail_url text, is_active boolean not null default true, sort_order int not null default 0, seo_title varchar(200), seo_description varchar(500), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table dpg_app.blog_tags (id serial primary key, name varchar(50) not null, slug varchar(50) not null unique, description text, post_count int not null default 0, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table dpg_app.blog_posts (id serial primary key, title varchar(300) not null, slug varchar(300) not null unique, excerpt text, content text not null default '', category_id int not null references dpg_app.blog_categories(id), thumbnail_url text, cover_image_url text, seo_title varchar(200), seo_description varchar(500), seo_keywords varchar(500), reading_time int, view_count int not null default 0, status varchar(20) not null default 'draft', published_at timestamptz, author_name varchar(100) not null default 'Ban Biên Tập Đông Phú Gia', author_avatar text, is_featured boolean not null default false, is_pinned boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), publishing_identity_id uuid, external_id varchar(200), version int not null default 1, first_published_at timestamptz, scheduled_for timestamptz, scheduled_timezone varchar(100), scheduled_version int, schedule_blocked_code varchar(100), schedule_blocked_at timestamptz, schedule_last_attempt_at timestamptz);
create table dpg_app.blog_post_tags (post_id int not null references dpg_app.blog_posts(id) on delete cascade, tag_id int not null references dpg_app.blog_tags(id) on delete cascade, primary key (post_id, tag_id));
create table dpg_app.banners (id serial primary key, title varchar(200), image_url varchar(500) not null, link_url varchar(500), is_active boolean not null default true, sort_order int not null default 0, created_at timestamp default current_timestamp, updated_at timestamp default current_timestamp, brand_id int, category_id int, position varchar(50) default 'HERO');
create table dpg_app.partners (id serial primary key, name varchar(200) not null, slug varchar(200) not null unique, logo_url varchar(500), description text, tier varchar(50) default 'Vàng', gradient_class varchar(100), link_url varchar(500), is_active boolean default true, sort_order int default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table dpg_app.projects (id serial primary key, title varchar(200) not null, slug varchar(200) not null unique, location varchar(200), thumbnail_url varchar(500), description text, category varchar(100), tags text[] default '{}', is_featured boolean default false, is_active boolean default true, sort_order int default 0, created_at timestamptz default now(), updated_at timestamptz default now());
alter table dpg_app.blog_categories enable row level security; alter table dpg_app.blog_tags enable row level security; alter table dpg_app.blog_posts enable row level security;
alter table dpg_app.blog_post_tags enable row level security; alter table dpg_app.banners enable row level security; alter table dpg_app.partners enable row level security; alter table dpg_app.projects enable row level security;
-- Base-fixture tables extended with the real columns used by the resources.
alter table dpg_app.categories add column description text, add column thumbnail_url varchar(1000), add column icon_name varchar(50), add column sort_order int not null default 0, add column seo_title varchar(200), add column seo_description varchar(500), add column banner_url varchar(1000), add column created_at timestamptz not null default now(), add column updated_at timestamptz not null default now();
alter table dpg_app.subcategories add column sort_order int not null default 0;
alter table dpg_app.brands add column logo_url varchar(1000), add column description text, add column origin_country varchar(100), add column website_url varchar(500), add column is_featured boolean not null default false, add column sort_order int not null default 0, add column created_at timestamptz not null default now(), add column updated_at timestamptz not null default now();
create unique index admin_users_email_uq on dpg_app.admin_users (email);
create unique index admin_users_username_uq on dpg_app.admin_users (username);
create table dpg_app.catalog_taxons (id serial primary key, parent_id int references dpg_app.catalog_taxons(id), name varchar(200) not null, slug varchar(200) not null, canonical_path varchar(500) not null, depth int not null default 0, sort_order int not null default 0, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), kind varchar(40) not null default 'type', status varchar(40) not null default 'active', seo_title varchar(200), seo_description varchar(500), is_indexable boolean not null default true, is_listing_enabled boolean not null default true);
create table dpg_app.product_types (id serial primary key, subcategory_id int not null references dpg_app.subcategories(id), slug varchar(100) not null, name varchar(200) not null, description text, sort_order int not null default 0, is_active boolean not null default true, filter_policy jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table dpg_app.product_sub_types (id serial primary key, product_type_id int not null references dpg_app.product_types(id), slug varchar(100) not null, name varchar(200) not null, sort_order int not null default 0, is_active boolean not null default true);
create table dpg_app.spec_definitions (id serial primary key, key varchar(120) not null unique, label varchar(200) not null, data_type varchar(30) not null default 'text', unit varchar(30), is_filterable boolean not null default false, is_pdp_visible boolean not null default true, is_reserved boolean not null default false, sort_order int not null default 0, normalize_rule jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table dpg_app.spec_options (id serial primary key, spec_definition_id int not null references dpg_app.spec_definitions(id), value varchar(200) not null, slug varchar(160) not null, sort_order int not null default 0, aliases text[] not null default '{}', is_active boolean not null default true);
create table dpg_app.customers (id serial primary key, full_name varchar(200) not null, phone varchar(20) not null unique, email varchar(200), source varchar(50) default 'MANUAL', notes text, last_interacted_at timestamptz default now(), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table dpg_app.catalog_taxons enable row level security; alter table dpg_app.product_types enable row level security; alter table dpg_app.product_sub_types enable row level security;
alter table dpg_app.spec_definitions enable row level security; alter table dpg_app.spec_options enable row level security; alter table dpg_app.customers enable row level security;
